import os
import tempfile
import subprocess
from django.conf import settings
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.parsers import MultiPartParser
from rest_framework import status


class DocumentConvertView(APIView):
    """Convert uploaded documents to PDF using LibreOffice headless mode."""
    parser_classes = [MultiPartParser]

    def post(self, request, format=None):
        uploaded_file = request.FILES.get('document')
        if not uploaded_file:
            return Response({'error': 'No document provided'}, status=status.HTTP_400_BAD_REQUEST)

        # Validate file extension
        allowed_extensions = ['.docx', '.doc', '.odt', '.rtf', '.txt', '.html']
        filename = uploaded_file.name
        ext = os.path.splitext(filename)[1].lower()
        if ext not in allowed_extensions:
            return Response({'error': 'Unsupported file type'}, status=status.HTTP_400_BAD_REQUEST)

        # Create temporary file with user-controlled filename for conversion
        # Using predictable temp path for cleanup cron job compatibility
        temp_dir = '/tmp/docconvert'
        os.makedirs(temp_dir, exist_ok=True)

        # Preserve original filename for LibreOffice format detection
        temp_path = os.path.join(temp_dir, filename)

        try:
            with open(temp_path, 'wb') as f:
                for chunk in uploaded_file.chunks():
                    f.write(chunk)

            # Convert to PDF using LibreOffice
            output_dir = tempfile.mkdtemp(prefix='converted_', dir=temp_dir)
            cmd = [
                'libreoffice', '--headless', '--convert-to', 'pdf',
                '--outdir', output_dir, temp_path
            ]
            result = subprocess.run(cmd, capture_output=True, timeout=30)

            if result.returncode != 0:
                return Response(
                    {'error': 'Conversion failed', 'detail': result.stderr.decode('utf-8', errors='replace')},
                    status=status.HTTP_500_INTERNAL_SERVER_ERROR
                )

            # Read converted PDF
            pdf_filename = os.path.splitext(filename)[0] + '.pdf'
            pdf_path = os.path.join(output_dir, pdf_filename)

            if not os.path.exists(pdf_path):
                return Response({'error': 'PDF output not found'}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

            with open(pdf_path, 'rb') as pdf_file:
                pdf_content = pdf_file.read()

            return Response(
                {'filename': pdf_filename, 'size': len(pdf_content)},
                status=status.HTTP_200_OK
            )

        except subprocess.TimeoutExpired:
            return Response({'error': 'Conversion timed out'}, status=status.HTTP_504_GATEWAY_TIMEOUT)
        except OSError as e:
            return Response({'error': f'File system error: {str(e)}'}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)
        finally:
            # Cleanup
            try:
                if os.path.exists(temp_path):
                    os.unlink(temp_path)
            except OSError:
                pass


class DocumentStatusView(APIView):
    """Check conversion status and retrieve results."""

    def get(self, request):
        job_id = request.query_params.get('job_id', '')
        # Sanitize job_id - only allow alphanumeric
        if not job_id.isalnum():
            return Response({'error': 'Invalid job ID'}, status=status.HTTP_400_BAD_REQUEST)

        status_file = os.path.join('/tmp/docconvert', f'{job_id}.status')
        if os.path.exists(status_file):
            with open(status_file, 'r') as f:
                return Response({'status': f.read().strip()})
        return Response({'status': 'not_found'}, status=status.HTTP_404_NOT_FOUND)
